apply_patch <<'PATCH'
*** Begin Patch
*** Update File: /src/libxml2/buf.c
@@
 int
 xmlBufSetInputBaseCur(xmlBufPtr buf, xmlParserInputPtr input,
                       size_t base, size_t cur) {
+    /*
+     * Error sentinel for parser inputs.
+     *
+     * When a buffer enters an error state, callers might still access
+     * input->cur (and potentially advance it by one) before the error
+     * propagates. Using a padded static NUL buffer avoids one-past reads
+     * from the empty string literal (""), which has size 1.
+     */
+    static const xmlChar xmlBufEmpty[2] = { 0, 0 };
+
     if (input == NULL)
         return(-1);
     if ((buf == NULL) || (buf->error)) {
-        input->base = input->cur = input->end = BAD_CAST "";
+        input->base = input->cur = xmlBufEmpty;
+        input->end = xmlBufEmpty + 1;
         return(-1);
     }
*** End Patch
PATCH

perl -0777 -i -pe 's/static const xmlChar xmlBufEmpty\[2\] = \{ 0, 0 \};/static const xmlChar xmlBufEmpty[64] = { 0 };/s; s/input->end = xmlBufEmpty \+ 1;/input->end = xmlBufEmpty + sizeof(xmlBufEmpty) - 1;/s' /src/libxml2/buf.c

# Patch xmlParseNCName: reorder bounds checks and guard against cur>=end
perl -0777 -i -pe 's/in = ctxt->input->cur;
\s*e = ctxt->input->end;
\s*if \(\(\(\(\*in >= 0x61\) && \(\*in <= 0x7A\)\) \|\|
\s*\(\(\*in >= 0x41\) && \(\*in <= 0x5A\)\) \|\|
\s*\(\*in == _\)\) && \(in < e\)\) \{/in = ctxt->input->cur;
    e = ctxt->input->end;
    if (in >= e)
        goto complex;
    if ((in < e) && (((*in >= 0x61) && (*in <= 0x7A)) ||
	 ((*in >= 0x41) && (*in <= 0x5A)) ||
	 (*in == _))) {/s; s/while \(\(\(\(\*in >= 0x61\) && \(\*in <= 0x7A\)\) \|\|
\s*\(\(\*in >= 0x41\) && \(\*in <= 0x5A\)\) \|\|
\s*\(\(\*in >= 0x30\) && \(\*in <= 0x39\)\) \|\|
\s*\(\*in == _\) \|\| \(\*in == -\) \|\|
\s*\(\*in == \.\)\) && \(in < e\)\)
\s*in\+\+;/while ((in < e) && (((*in >= 0x61) && (*in <= 0x7A)) ||
	        ((*in >= 0x41) && (*in <= 0x5A)) ||
	        ((*in >= 0x30) && (*in <= 0x39)) ||
	        (*in == _) || (*in == -) ||
	        (*in == .)))
            in++;/s' /src/libxml2/parser.c

# Patch xmlParseNCNameComplex: validate pointers and bounds before dict lookup
perl -0777 -i -pe 's//\*
\s*Handler for more complex cases
\s*\*/
\s*startPosition = CUR_PTR - BASE_PTR;//\*
     * Handler for more complex cases
     */
    if ((ctxt->input == NULL) || (ctxt->input->base == NULL) ||
        (ctxt->input->cur == NULL) || (ctxt->input->end == NULL) ||
        (ctxt->input->cur >= ctxt->input->end)) {
        return(NULL);
    }
    startPosition = CUR_PTR - BASE_PTR;/s; s/return\(xmlDictLookup\(ctxt->dict, \(BASE_PTR \+ startPosition\), len\)\);/do {
        size_t avail = (size_t)(ctxt->input->end - ctxt->input->base);
        if ((startPosition > avail) || ((size_t)len > avail - startPosition))
            return(NULL);
        return(xmlDictLookup(ctxt->dict, (BASE_PTR + startPosition), len));
    } while (0);/s' /src/libxml2/parser.c

